with
ml_cds_features_cte as (
	SELECT customerid, updated_at, latitude, longitude, customergender, own_the_land_for_product_installation__c, how_long_have_you_had_the_same_phone_no__c, how_long_have_you_been_a_farmer__c, number_of_household_members__c, 
	pest_disease_control_pest_type_usage_c, total_income__c, total_expenses__c, no_of_months_to_finish_paying_loan_s_c, currently_have_any_outstanding_loans_c, total_amount_of_outstanding_loan_s_c, amount_left_after_monthly_expenses_c, 
	amount_paid_for_getting_water_each_week__c, main_source_of_income_c, no_of_family_members_friends_helping_c, main_purpose_of_acquiring_the_pump_c, primary_decision_maker_to_buy_product_c, other_sources_of_water_c, amount_paid_for_water_other_pump_usage__c, 
	hours_spent_fetching_water_every_week__c, do_you_have_animals_c, number_of_pigs_c, number_of_cows_c, number_of_sheep_c, number_of_goats_c, number_of_working_age_adults_in_the_hh__c, farm_acreage_c, number_of_pensioners_living_in_the_hh__c, 
	number_of_financial_dependants__c, been_living_in_the_same_location_for__c, compensation_for_the_help_provided__c, harvest_cycle_per_year__c, quantity_of_water_usage_per_week__c, types_of_crops_grown_c, type_of_fruits_and_vegetables_grown_, _feature_generated_at, _exported_at
